LAKE = (360, 512, 1512, 575)           # the lake surface (left, top, right, bottom)
MOON = (1432, 97, 64)                  # moon centre and radius
PNG = {
  'cloud_a': ('png', ''),
  'cloud_b': ('png', ''),
  'cloud_c': ('png', ''),
  'cloud_d': ('png', ''),
  'menu_bg': ('jpg', ''),
  'menu_record': ('png', ''),
  'menu_title': ('png', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
